#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>

using Interval = std::pair<int, int>;

std::vector<Interval> insertInterval(const std::vector<Interval>& intervals, Interval newInterval) {
    std::vector<Interval> result;
    std::size_t i = 0;
    // The intervals that end before the new one starts stay as they are.
    while (i < intervals.size() && intervals[i].second < newInterval.first) {
        result.push_back(intervals[i]);
        i++;
    }
    // The ones that overlap it merge into it.
    while (i < intervals.size() && intervals[i].first <= newInterval.second) {
        newInterval.first = std::min(newInterval.first, intervals[i].first);
        newInterval.second = std::max(newInterval.second, intervals[i].second);
        i++;
    }
    result.push_back(newInterval);
    // The rest start after it ends.
    result.insert(result.end(), intervals.begin() + i, intervals.end());
    return result;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<Interval> intervals(n);
    for (int i = 0; i < n; i++) {
        std::cin >> intervals[i].first >> intervals[i].second;
    }
    Interval newInterval;
    std::cin >> newInterval.first >> newInterval.second;
    for (const Interval& interval : insertInterval(intervals, newInterval)) {
        std::cout << interval.first << " " << interval.second << "\n";
    }
    return 0;
}

