import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

type Interval = [number, number];

function insertInterval(intervals: Interval[], newInterval: Interval): Interval[] {
  const result: Interval[] = [];
  let [start, end] = newInterval;
  let i = 0;
  let current = intervals[i];
  // The intervals that end before the new one starts stay as they are.
  while (current !== undefined && current[1] < start) {
    result.push(current);
    i++;
    current = intervals[i];
  }
  // The ones that overlap it merge into it.
  while (current !== undefined && current[0] <= end) {
    start = Math.min(start, current[0]);
    end = Math.max(end, current[1]);
    i++;
    current = intervals[i];
  }
  result.push([start, end]);
  // The rest start after it ends.
  result.push(...intervals.slice(i));
  return result;
}

